"""SwiftSage's ReAct baseline on ScienceWorld, as run by mb/official/run_swiftsage.py (--agent react).

Source: SwiftSage (Lin et al. 2023), branch science_world, baselines/eval_agent_react.py and
eval_utils.findValidActionNew (vendored in mb/evolve/seeds_src/swiftsage_*). What the model sees,
call for call, is what that loop sends:
  * one user message, no system message: 'Interact with a household to solve a task. Here is an
    example.\\n' + the task's demo (prompt.jsonl, embedded below as DEMOS) + '\\n\\nHere is the
    task.\\n' + clean(first obs) + '\\n' + task description without its 'Task Description:\\n'
    header + '\\n>', then ' <action>\\n<obs>\\n>' per step;
  * cut from the front, one '>'-step at a time (demo first, then the episode), while the prompt is
    over 4096 - 60 gpt-3.5-turbo (cl100k) tokens;
  * temperature 0, max_tokens 50, top_p 1, stop ["\\n"] (frequency/presence penalty 0 and n=1 are
    the API defaults, so they are not sent); the reply is stripped;
  * 'think: ...' replies are answered 'OK.' without touching the env; any other reply is mapped onto
    a valid action by findValidActionNew (exact match after excluding the last 3 actions, door and
    focus filters, else the valid action with the largest token overlap, sanitised);
  * stop at 2 * env_step_limit (= 200) iterations, think steps included, or when the last 5 actions
    hold exactly 2 distinct ones; the env itself ends on a negative score or after env_step_limit
    (100) moves.

Three things the official loop reads are not in what the adapter (mb/benches/sciworld.py) passes
to a harness, so they are recovered or approximated here:
  * which task it is (it picks the demo): recognised from the task description's template
    (`task_name`; it matches every variation sampled and every demo, see check_equiv.py);
  * the tokenizer: `count_tokens` from harness_lib if it provides one (exact if it wraps
    tiktoken's gpt-3.5-turbo encoding), otherwise `approx_tokens`, a cl100k pre-tokenizer count;
  * ScienceWorld's `info['look']` and `env.inventory()` (findValidActionNew's focus filter): used if
    the env exposes them as `env.info` (a dict with 'look' and 'inv'); otherwise the focus filter
    is skipped (every valid focus action, minus agent/air/rooms, is kept).
The valid combinations are the adapter's `admissible()` (ScienceWorld's info['valid'] after the last
step) where SwiftSage makes a fresh getValidActionObjectCombinations() call; ScienceWorld names
ambiguous referents differently from call to call, so the two are equally good samples of the same
thing, not the same list.
The env step budget is the adapter's (100 actions, every action counted; 250 on three tasks) where
SwiftSage's is ScienceWorld's own (`moves > 100` ends the episode; look around / inventory / task
and unparsed input cost no move, some actions cost more than one); this seed also stops after
ENV_STEP_LIMIT + 1 env actions, which is where SwiftSage stops when every action costs one move.
"""
import re

try:
    from harness_lib import count_tokens
except ImportError:
    count_tokens = None

ENV_STEP_LIMIT = 100
MAX_ITERATIONS = 2 * ENV_STEP_LIMIT
MAX_LEN = 4096
HEADER = "Task Description:\n"
VALID_MARK = "\n\nValid actions (replace OBJ with the name of an object you can see): "
ROOMS = ["hallway", "greenhouse", "green house", "kitchen", "bathroom", "outside", "workshop", "art studio",
         "foundry", "bedroom", "living room"]

# cl100k_base's pre-tokenizer with `re` classes: each piece is one token for common English words
# and numbers of up to 3 digits; longer letter runs get one more token per LONG_RUN letters.
PRETOKEN = re.compile(r"(?i:'s|'t|'re|'ve|'m|'ll|'d)|(?:[^\r\n\w]|_)?[^\W\d_]+|\d{1,3}"
                      r"| ?(?:[^\s\w]|_)+[\r\n]*|\s*[\r\n]+|\s+(?!\S)|\s+")
LONG_RUN = 11      # calibrated against tiktoken in check_equiv.py


def approx_tokens(text):
    n = 0
    for m in PRETOKEN.finditer(text):
        piece = m.group(0)
        n += 1
        letters = len(piece.strip())
        if letters > LONG_RUN and piece.strip().isalpha():
            n += (letters - 1) // LONG_RUN
    return n


def n_tokens(text):
    return count_tokens(text) if count_tokens is not None else approx_tokens(text)


def task_name(desc):
    """The ScienceWorld task a description belongs to, from the 30 tasks' description templates."""
    d = desc[len(HEADER):] if desc.startswith(HEADER) else desc

    def has(s):
        return s in d
    if has("Your task is to boil "):
        return "boil"
    if has("Your task is to melt "):
        return "melt"
    if has("Your task is to freeze "):
        return "freeze"
    if has("change the state of matter of"):
        return "change-the-state-of-matter-of"
    if has("measure the temperature of"):
        return "use-thermometer"
    m = re.search(r"measure the melting point of (.*?), which", d)
    if m or has("measure the melting point of"):
        return ("measure-melting-point-unknown-substance" if m and "unknown substance" in m.group(1)
                else "measure-melting-point-known-substance")
    if has("renewable power source"):
        return "power-component-renewable-vs-nonrenewable-energy"
    if has("Your task is to turn on the"):
        return "power-component"
    m = re.search(r"determine if (.*?) is electrically conductive", d)
    if m:
        return ("test-conductivity-of-unknown-substances" if "unknown substance" in m.group(1)
                else "test-conductivity")
    m = re.search(r"find a\(n\) (non-living thing|living thing|plant|animal)\.", d)
    if m:
        return "find-" + m.group(1).replace(" ", "-")
    if has("plant from seed"):
        return "grow-plant"
    if has("Your task is to grow a"):
        return "grow-fruit"
    if has("use chemistry to create the substance"):
        return "chemistry-mix"
    if has("use chemistry to create") and has("part-way done"):
        return "chemistry-mix-paint-tertiary-color"
    if has("use chemistry to create"):
        return "chemistry-mix-paint-secondary-color"
    if has("longest life span, then the shortest"):
        return "lifespan-longest-lived-then-shortest-lived"
    if has("animal with the longest life span"):
        return "lifespan-longest-lived"
    if has("animal with the shortest life span"):
        return "lifespan-shortest-lived"
    if re.search(r"life stages of the .* plant", d):
        return "identify-life-stages-2"
    if has("life stages of"):
        return "identify-life-stages-1"
    if has("inclined plane") and has("angle"):
        return "inclined-plane-determine-angle"
    if has("inclined plane") and has("unknown material"):
        return "inclined-plane-friction-unnamed-surfaces"
    if has("inclined plane"):
        return "inclined-plane-friction-named-surfaces"
    if re.search(r"trait in the unknown \w+ plant", d):
        return "mendelian-genetics-unknown-plant"
    if has("dominant or recessive"):
        return "mendelian-genetics-known-plant"
    return None


def clean(s):
    for tok in ["\n", "\t"]:
        s = s.replace(tok, " ")
    return s


def look_and_inventory(env):
    """ScienceWorld's info['look'] and inventory text, when the env passes them on; else None."""
    try:
        info = env.info
    except AttributeError:
        return None
    if not info or "look" not in info or "inv" not in info:
        return None
    return info["look"], info["inv"]


def find_valid_action(predictions, valid_combos, look_inv, recent_actions, k=5):
    """eval_utils.findValidActionNew with sbert_model=None (token-overlap matching), unchanged
    except that the valid combinations, look and inventory are passed in."""
    valid_open_door = ["open door to " + i for i in ROOMS]
    invalid_focus = ["focus on " + x for x in ["agent", "air"] + ROOMS]
    valid_actions = set(valid_combos)
    valid_actions.update(valid_open_door)
    valid_actions.difference_update(invalid_focus)
    if look_inv is not None:
        look, inventory = look_inv[0], look_inv[1].lower()
    valid_actions.difference_update(recent_actions[-3:])
    for va in list(valid_actions):
        if "door" in va and "open" not in va:
            valid_actions.remove(va)
            continue
        if va.startswith("focus on") and look_inv is not None:
            pattern = re.compile(r"\b(?:focus|on|in|to)\b", re.IGNORECASE)
            used_objs = pattern.sub("", va).split(" ")
            valid = True
            for obj in used_objs:
                if obj not in look + " " + inventory:
                    valid = False
            if not valid:
                valid_actions.remove(va)
    for pred in predictions[:k]:
        pred = pred.replace("green house", "greenhouse")
        if pred.strip() in valid_actions:
            return pred.strip()
    valid_actions = list(valid_actions)
    valid_actions.sort(key=lambda x: len(x))
    top_value = 0.0
    top_action = predictions[0]
    unique_tokens_pred = set(predictions[0].split(" "))
    for valid_action in valid_actions:
        intersection = unique_tokens_pred.intersection(set(valid_action.split(" ")))
        if len(intersection) > top_value:
            top_action = valid_action
            top_value = len(intersection)
    return re.sub(r"[^A-Za-z0-9 ]+", "", top_action)


def split_instructions(text):
    """(task description with its header, first observation) from the adapter's instructions."""
    k = text.find(VALID_MARK)
    if k < 0:
        return text, ""
    rest = text[k + len(VALID_MARK):]
    j = rest.find("\n\n")
    return text[:k], (rest[j + 2:] if j >= 0 else "")


def fit(init_prompt, prompt):
    while n_tokens(init_prompt + prompt) > MAX_LEN - 60:
        index1 = init_prompt.find(">")
        if index1 == -1:
            index1_prompt = prompt.find(">")
            index2_prompt = prompt.find(">", index1_prompt + 1)
            prompt = prompt[:index1_prompt] + prompt[index2_prompt:]
        else:
            index2 = init_prompt.find(">", index1 + 1)
            if index2 == -1:
                init_prompt = init_prompt[:index1]
            else:
                init_prompt = init_prompt[:index1] + init_prompt[index2:]
    return init_prompt, prompt


def run_episode(env, chat):
    desc, obs = split_instructions(env.instructions)
    task = task_name(desc)
    demo = DEMOS.get(task, "")
    # SwiftSage: task_description = env.taskdescription()[18:], i.e. without "Task Description:\n";
    # the adapter's get_task_description() has no header, so there is nothing to cut.
    task_description = desc[len(HEADER):] if desc.startswith(HEADER) else desc
    recent_actions = ["look around"]
    init_prompt = "Interact with a household to solve a task. Here is an example.\n" + demo
    prompt = "\n\nHere is the task.\n" + clean(obs) + "\n" + task_description + "\n>"
    step = 0
    env_actions = 0
    while not env.done:
        init_prompt, prompt = fit(init_prompt, prompt)
        action = (chat([{"role": "user", "content": init_prompt + prompt}], temperature=0, max_tokens=50,
                       top_p=1, stop=["\n"]) or "").strip()
        if action.startswith("think:"):
            obs = "OK."
        else:
            action = find_valid_action([action], env.admissible() or [], look_and_inventory(env),
                                       recent_actions)
            obs = env.act(action)
            env_actions += 1
        obs = clean(obs)
        prompt += f" {action}\n{obs}\n>"
        recent_actions.append(action)
        step += 1
        if step >= MAX_ITERATIONS or env.done or env_actions > ENV_STEP_LIMIT:
            break
        if len(recent_actions) >= 5 and len(set(recent_actions[-5:])) == 2:
            break


